INSERT INTO topics (id, name, icon, description, slug, sort_order) VALUES ('chat', '日常聊天', '聊', '从一句问候，开始自然的对话。', 'chat', 1);
INSERT INTO topics (id, name, icon, description, slug, sort_order) VALUES ('food', '吃饭', '食', '一起吃什么，也一起聊什么。', 'food', 2);
