INSERT INTO concepts (id, slug, topic_id, zh, sort_order) VALUES (1, 'concept-1', 'chat', '你在干嘛？', 1);
INSERT INTO comparisons (concept_id, explanation) VALUES (1, '英语用 are you doing 询问当下动作；日语用「しているの」，聊天时通常省略「你」。');
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (1, 'en', '询问正在做的事', 'are + 动词-ing，让问题落在现在这一刻。', 'What are you reading? 你在看什么？');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (1, 1, 'en', 'What are you doing?', '/wʌt ɑr ju ˈduɪŋ/', NULL, 2, 1);
INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (100, 1, 'en', 1, 'What', '[]', 0);
INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (101, 1, 'en', 1, 'are you doing', '[]', 1);
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (2, 'ja', '放进情境里理解', 'を标记动作涉及的对象；している表示正在做，の让朋友间的提问自然。', '何を見ているの？你在看什么？');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (2, 1, 'ja', '何をしているの？', NULL, 'なにをしているの？', 2, 2);
