INSERT INTO expression_readings (expression_id, sort_order, text, reading) VALUES (2, 1, 'をしているの？', NULL);
INSERT INTO concepts (id, slug, topic_id, zh, sort_order) VALUES (2, 'concept-2', 'chat', '我刚起床。', 2);
INSERT INTO comparisons (concept_id, explanation) VALUES (2, '英语用 just 加过去式；日语用「たところ」强调动作刚结束。两句都适合告诉朋友自己的近况。');
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (3, 'en', '刚刚发生的事', 'just 搭配过去式 woke up，表示起床这件事刚发生。', 'I just got home. 我刚到家。');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (3, 2, 'en', 'I just woke up.', '/aɪ dʒʌst woʊk ʌp/', NULL, 2, 3);
