INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (301, 3, 'en', 3, 'just woke up', '[]', 1);
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (4, 'ja', '放进情境里理解', '动词过去式 + ところ，表示刚做完某事。这里是刚起床。', '今帰ったところ。刚刚回来。');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (4, 2, 'ja', '今起きたところ。', NULL, 'いまおきたところ。', 3, 4);
