INSERT INTO concepts (id, slug, topic_id, zh, sort_order) VALUES (3, 'concept-3', 'chat', '我有点累。', 3);
INSERT INTO comparisons (concept_id, explanation) VALUES (3, '英语用 be tired 描述状态；日语常用「疲れた」表示已经累了。不要逐字把日语过去式理解成「以前累」。');
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (5, 'en', '把语气放轻一点', 'a little 表示有点，放在 tired 前面，让程度听起来不强。', 'I’m a little busy. 我有点忙。');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (5, 3, 'en', 'I’m a little tired.', '/aɪm ə ˈlɪtəl taɪrd/', NULL, 1, 5);
INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (500, 5, 'en', 5, 'I’m', '[]', 0);
INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (501, 5, 'en', 5, 'a little tired', '[]', 1);
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (6, 'ja', '放进情境里理解', 'ちょっと表示有点；疲れた虽然是过去式，却常用来表达现在累了的状态。', 'ちょっとお腹がすいた。有点饿了。');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (6, 3, 'ja', 'ちょっと疲れた。', NULL, 'ちょっとつかれた。', 2, 6);
INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (600, 6, 'ja', 6, 'ちょっと', '[{"text":"ちょっと"}]', 0);
INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (601, 6, 'ja', 6, '疲れた', '[{"text":"疲","reading":"つか"},{"text":"れた"}]', 1);
