INSERT INTO concepts (id, slug, topic_id, zh, sort_order) VALUES (4, 'concept-4', 'chat', '我不知道。', 4);
INSERT INTO comparisons (concept_id, explanation) VALUES (4, '面对一个答不出来的问题，英语说 don’t know，日语可以说「わからない」。日语会根据「不理解」还是「没有相关知识」选择表达。');
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (7, 'en', '表达不知道', 'don’t + 动词原形，用来否定 know。可在前面加 Sorry，让回答柔和。', 'Sorry, I don’t know his name. 抱歉，我不知道他的名字。');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (7, 4, 'en', 'I don’t know.', '/aɪ doʊnt noʊ/', NULL, 1, 7);
INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (700, 7, 'en', 7, 'I', '[]', 0);
INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (701, 7, 'en', 7, 'don’t know', '[]', 1);
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (8, 'ja', '放进情境里理解', 'わからない表示不明白、不知道答案；如果是从没听说过某事，常用知らない。', '答えがわからない。不知道答案。');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (8, 4, 'ja', 'わからない。', NULL, 'わからない。', 1, 8);
INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (800, 8, 'ja', 8, 'わからない', '[{"text":"わからない"}]', 0);
INSERT INTO expression_readings (expression_id, sort_order, text, reading) VALUES (8, 0, 'わからない。', NULL);
INSERT INTO concepts (id, slug, topic_id, zh, sort_order) VALUES (5, 'concept-5', 'chat', '等一下。', 5);
INSERT INTO comparisons (concept_id, explanation) VALUES (5, '英语用动词原形开头；日语用「て形」请求对方行动。a second 和「ちょっと」都把等待说得轻一点。');
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (9, 'en', '简短的请求', '以动词 Wait 开头，是直接的请求；a second 在这里是片刻，并非严格的一秒。', 'Wait a minute, please. 请等一下。');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (9, 5, 'en', 'Wait a second.', '/weɪt ə ˈsɛkənd/', NULL, 1, 9);
INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (900, 9, 'en', 9, 'Wait', '[]', 0);
INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (901, 9, 'en', 9, 'a second', '[]', 1);
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (10, 'ja', '放进情境里理解', '待って是待つ的て形，用来向熟悉的人提出请求；加ください会更礼貌。', 'ここで待ってください。请在这里等。');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (10, 5, 'ja', 'ちょっと待って。', NULL, 'ちょっとまって。', 2, 10);
