INSERT INTO expression_readings (expression_id, sort_order, text, reading) VALUES (10, 2, 'って。', NULL);
INSERT INTO concepts (id, slug, topic_id, zh, sort_order) VALUES (6, 'concept-6', 'food', '我饿了。', 6);
INSERT INTO comparisons (concept_id, explanation) VALUES (6, '英语用形容词 hungry 描述自己；日语说「肚子空了」。同一感受不需要逐词对齐。');
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (11, 'en', '描述身体感受', 'be + hungry 描述现在的饥饿状态。very hungry 表示很饿。', 'I’m thirsty. 我渴了。');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (11, 6, 'en', 'I’m hungry.', '/aɪm ˈhʌŋɡri/', NULL, 1, 11);
