INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (12, 'ja', '放进情境里理解', 'お腹がすいた是自然的「饿了」；が连接肚子与状态变化。', 'お腹がすきました。我饿了（礼貌）。');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (12, 6, 'ja', 'お腹がすいた。', NULL, 'おなかがすいた。', 2, 12);
