INSERT INTO concepts (id, slug, topic_id, zh, sort_order) VALUES (7, 'concept-7', 'food', '你想吃什么？', 7);
INSERT INTO comparisons (concept_id, explanation) VALUES (7, '英语用 want to eat；日语把食べる变成「食べたい」。两者都以对方的意愿为中心。');
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (13, 'en', '询问对方的想法', 'want to + 动词，表示想做某事；What 提问想吃的东西。', 'What do you want to drink? 你想喝什么？');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (13, 7, 'en', 'What do you want to eat?', '/wʌt də ju wɑnt tə it/', NULL, 2, 13);
INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (1300, 13, 'en', 13, 'What', '[]', 0);
INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (1301, 13, 'en', 13, 'do you want to eat', '[]', 1);
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (14, 'ja', '放进情境里理解', '食べたい表示想吃；想吃的东西可以用が标记。和朋友说话可省略ですか。', '何が飲みたい？你想喝什么？');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (14, 7, 'ja', '何が食べたい？', NULL, 'なにがたべたい？', 2, 14);
