INSERT INTO concepts (id, slug, topic_id, zh, sort_order) VALUES (8, 'concept-8', 'food', '我还没吃饭。', 8);
INSERT INTO comparisons (concept_id, explanation) VALUES (8, '英语用现在完成时加 yet；日语用「まだ + ていません」。重点都是「截至现在还没有」，日语不必说出主语。');
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (15, 'en', '到现在还没做', 'have + 过去分词连接过去与现在；haven’t eaten + yet 表示到现在还没吃。', 'I haven’t finished yet. 我还没完成。');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (15, 8, 'en', 'I haven’t eaten yet.', '/aɪ ˈhævənt ˈitən jɛt/', NULL, 3, 15);
INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (1500, 15, 'en', 15, 'I', '[]', 0);
