INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (16, 'ja', '放进情境里理解', 'まだ + ていません表示某件事到现在还没发生。这里是礼貌地说还没吃。', 'まだ決めていません。还没决定。');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (16, 8, 'ja', 'まだ食べていません。', NULL, 'まだたべていません。', 3, 16);
