INSERT INTO concepts (id, slug, topic_id, zh, sort_order) VALUES (9, 'concept-9', 'food', '这个辣吗？', 9);
INSERT INTO comparisons (concept_id, explanation) VALUES (9, '英语把 is 提到句首表示提问；日语在句末用「か」。两句都可以指着食物使用。');
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (17, 'en', '确认食物的味道', '把 is 放到 this 前面，就能询问它是否有某种特征。', 'Is this sweet? 这个甜吗？');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (17, 9, 'en', 'Is this spicy?', '/ɪz ðɪs ˈspaɪsi/', NULL, 1, 17);
