INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (18, 'ja', '放进情境里理解', 'これは指出话题；辛い描述辣；ですか构成礼貌的问句。', 'これは甘いですか？这个甜吗？');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (18, 9, 'ja', 'これは辛いですか？', NULL, 'これはからいですか？', 1, 18);
