INSERT INTO concepts (id, slug, topic_id, zh, sort_order) VALUES (10, 'concept-10', 'food', '我吃饱了。', 10);
INSERT INTO comparisons (concept_id, explanation) VALUES (10, '英语用 full 描述自己；日语用「お腹がいっぱい」描述肚子。与饿了的表达一起记，更容易在饭桌上使用。');
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (19, 'en', '说明已经够了', 'full 在吃饭语境里表示饱了，可以加 Thanks 来婉拒更多食物。', 'Thanks, I’m full. 谢谢，我吃饱了。');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (19, 10, 'en', 'I’m full.', '/aɪm fʊl/', NULL, 1, 19);
