INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (1901, 19, 'en', 19, 'full', '[]', 1);
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (20, 'ja', '放进情境里理解', 'いっぱい在这里表示满了，用肚子满了表达吃饱。', 'もうお腹がいっぱいです。我已经吃饱了。');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (20, 10, 'ja', 'お腹がいっぱい。', NULL, 'おなかがいっぱい。', 1, 20);
