INSERT INTO expression_readings (expression_id, sort_order, text, reading) VALUES (20, 2, 'がいっぱい。', NULL);
INSERT INTO concepts (id, slug, topic_id, zh, sort_order) VALUES (11, 'concept-11', 'school', '今天有课吗？', 11);
INSERT INTO comparisons (concept_id, explanation) VALUES (11, '英语说「我们有课吗」；日语常说「今天有课吗」，用あります表达安排的存在，不必出现「我们」。');
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (21, 'en', '确认共同安排', 'Do we have…? 询问大家是否有某个安排；today 指明时间。', 'Do we have homework today? 今天有作业吗？');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (21, 11, 'en', 'Do we have class today?', '/də wi hæv klæs təˈdeɪ/', NULL, 2, 21);
