INSERT INTO concepts (id, slug, topic_id, zh, sort_order) VALUES (12, 'concept-12', 'school', '我迟到了。', 12);
INSERT INTO comparisons (concept_id, explanation) VALUES (12, '英语常用现在状态 I’m late；日语可以用「遅れました」报告迟到这件事。向老师说时，加すみません更自然。');
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (23, 'en', '说明当前处境', 'be late 表示迟到的状态；加 for 可以说明迟到的是哪件事。', 'I’m late for class. 我上课迟到了。');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (23, 12, 'en', 'I’m late.', '/aɪm leɪt/', NULL, 1, 23);
INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (2300, 23, 'en', 23, 'I’m', '[]', 0);
INSERT INTO expression_chunks (id, expression_id, language, grammar_point_id, text, readings_json, sort_order) VALUES (2301, 23, 'en', 23, 'late', '[]', 1);
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (24, 'ja', '放进情境里理解', '遅れました是遅れる的礼貌过去式，用来报告自己来晚了。', 'すみません、遅れました。对不起，我迟到了。');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (24, 12, 'ja', '遅れました。', NULL, 'おくれました。', 2, 24);
