INSERT INTO concepts (id, slug, topic_id, zh, sort_order) VALUES (13, 'concept-13', 'school', '我听不懂。', 13);
INSERT INTO comparisons (concept_id, explanation) VALUES (13, '两句都指「听见了，但没理解内容」。英语用 what 引出内容；日语用「こと」把说的话作为理解的对象。');
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (25, 'en', '说明理解上的困难', 'what you’re saying 表示「你说的内容」，作为 understand 的对象。', 'I don’t understand this word. 我不懂这个词。');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (25, 13, 'en', 'I don’t understand what you’re saying.', '/aɪ doʊnt ˌʌndərˈstænd wʌt jʊr ˈseɪɪŋ/', NULL, 3, 25);
