INSERT INTO concepts (id, slug, topic_id, zh, sort_order) VALUES (14, 'concept-14', 'school', '什么时候截止？', 14);
INSERT INTO comparisons (concept_id, explanation) VALUES (14, '英语用 it 指已提到的作业，再用 due；日语直接把「締め切り」作为话题来问时间。');
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (27, 'en', '询问截止时间', 'due 在作业语境中表示到期、应交；When 用来问时间。', 'Is it due tomorrow? 是明天截止吗？');
INSERT INTO expressions (id, concept_id, language, text, ipa, hiragana, difficulty, grammar_point_id) VALUES (27, 14, 'en', 'When is it due?', '/wɛn ɪz ɪt du/', NULL, 2, 27);
