INSERT INTO concepts (id, slug, topic_id, zh, sort_order) VALUES (15, 'concept-15', 'school', '我还没写作业。', 15);
INSERT INTO comparisons (concept_id, explanation) VALUES (15, '中文说「写作业」，英语说 do homework，日语说「宿題をする」。表达同一任务时，搭配的动词不必和中文相同。');
INSERT INTO grammar_points (id, language, title, explanation, example) VALUES (29, 'en', '还没完成的任务', '英语自然说 do homework；haven’t done…yet 表示到现在尚未做。', 'I haven’t started my homework yet. 我还没开始写作业。');
